<?php $cantidadTotal=0; foreach($carrito as $item) $cantidadTotal += $item['cantidad']; ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pago - TecnoStore</title><link rel="stylesheet" href="assets/style.css"></head><body><aside><div class="brand">🛒 TecnoStore</div><div class="user">👤 <?=htmlspecialchars($_SESSION['usuario_nombre'])?><span>Cliente</span></div><nav><a href="index.php">🛍️ Catálogo</a><a class="active" href="index.php?accion=carrito">🛒 Mi carrito (<?=$cantidadTotal?>)</a><a href="index.php#contacto">📞 Atención</a></nav><a class="logout" href="index.php?controller=login&action=logout">🚪 Cerrar sesión</a></aside><main><header><div><h1>Finalizar compra</h1><p>Elige cómo quieres pagar y completa los datos.</p></div><a class="btn secondary" href="index.php?accion=carrito">← Volver al carrito</a></header><div class="payment-layout"><section class="payment-card"><h2>1. ¿Cómo quieres pagar?</h2><div class="payment-options"><label class="payment-option"><input type="radio" name="metodo_radio" value="yape" checked><span>📱</span><div><b>Yape</b><small>Pago mediante Yape</small></div></label><label class="payment-option"><input type="radio" name="metodo_radio" value="plin"><span>💜</span><div><b>Plin</b><small>Pago mediante Plin</small></div></label><label class="payment-option"><input type="radio" name="metodo_radio" value="tarjeta"><span>💳</span><div><b>Tarjeta</b><small>Débito o crédito</small></div></label><label class="payment-option"><input type="radio" name="metodo_radio" value="transferencia"><span>🏦</span><div><b>Transferencia bancaria</b><small>Realiza una transferencia</small></div></label><label class="payment-option"><input type="radio" name="metodo_radio" value="contra_entrega"><span>🚚</span><div><b>Pago contra entrega</b><small>Paga al recibir tu pedido</small></div></label></div><form method="post" action="index.php?accion=procesar_pago" id="paymentForm"><input type="hidden" name="metodo" id="metodo"><div id="paymentFields" class="payment-fields"></div><button class="btn payment-submit" type="submit">Confirmar compra</button></form></section><aside class="order-summary"><h2>Resumen</h2><?php foreach($carrito as $item): ?><div class="summary-item"><span><?=htmlspecialchars($item['nombre'])?> × <?=$item['cantidad']?></span><b>S/ <?=number_format($item['precio']*$item['cantidad'],2)?></b></div><?php endforeach; ?><hr><div class="summary-total"><span>Total a pagar</span><strong>S/ <?=number_format($total,2)?></strong></div></aside></div></main><script>const radios=document.querySelectorAll('input[name="metodo_radio"]');const fields=document.getElementById('paymentFields');const hidden=document.getElementById('metodo');function render(m){hidden.value=m;let html='';if(m==='yape'||m==='plin'){html='<div class="payment-info">📲 <b>Pago por '+(m==='yape'?'Yape':'Plin')+'</b><p>Ingresa el número de celular asociado y el código de operación.</p></div><label>Número de celular<input name="telefono" type="tel" inputmode="numeric" maxlength="9" placeholder="987654321" required></label><label>Código de operación<input name="codigo" maxlength="30" placeholder="Ej. 123456" required></label>';}else if(m==='tarjeta'){html='<div class="payment-info">💳 <b>Datos de tarjeta</b><p>Por seguridad, estos datos solo se usan para esta demostración y no se almacenan.</p></div><label>Nombre del titular<input name="titular" autocomplete="cc-name" placeholder="Como aparece en la tarjeta" required></label><label>Número de tarjeta<input name="numero_tarjeta" inputmode="numeric" maxlength="19" autocomplete="cc-number" placeholder="0000 0000 0000 0000" required></label><div class="two"><label>Vencimiento<input name="vencimiento" placeholder="MM/AA" maxlength="5" autocomplete="cc-exp" required></label><label>CVV<input name="cvv" type="password" inputmode="numeric" maxlength="4" autocomplete="cc-csc" placeholder="123" required></label></div>';}else if(m==='transferencia'){html='<div class="payment-info">🏦 <b>Datos para transferencia</b><p>Banco: TecnoStore Bank<br>Cuenta: 001-123456789<br>CCI: 00200100123456789012</p></div><label>Número de operación<input name="codigo" maxlength="30" placeholder="Ej. 123456" required></label>';}else{html='<div class="payment-info">🚚 <b>Pago contra entrega</b><p>Pagarás en efectivo o según los medios disponibles al momento de recibir tu pedido.</p></div><label>Dirección de entrega<input name="direccion" maxlength="200" placeholder="Ingresa tu dirección" required></label><label>Referencia<input name="referencia" maxlength="200" placeholder="Referencia para ubicarte" required></label>';}fields.innerHTML=html;}radios.forEach(r=>r.addEventListener('change',()=>render(r.value)));render(document.querySelector('input[name="metodo_radio"]:checked').value);</script></body></html>